import { KeyValueList } from '@refy-design/web';
import type { ComponentProps } from 'react';
const order = [
  { label: 'Placed on', value: 'Nov 21, 2026' },
  { label: 'Delivery', value: 'Standard', hint: '3 to 5 business days' },
  { label: 'Payment', value: 'Card ending in 4821' },
  { label: 'Total', value: '$ 184.90' },
];
export function Example() {
  const args: Pick<ComponentProps<typeof KeyValueList>, 'items' | 'title'> = {
    items: order,
    title: 'Order #48213',
  };
  return <KeyValueList {...args} />;
}

